<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>API Keys • Admin Console</title>
<style>
:root{--bg:#171819;--rail:#191a1c;--panel:#202226;--panel2:#25282d;--line:#363a42;--text:#e7e9ed;--muted:#9299a5;--blue:#4b9af5;--green:#22c77a;--orange:#f0a12c;--cyan:#16bfd0;--red:#ed626b}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px Inter,system-ui,-apple-system,Segoe UI,Arial;min-height:100vh}.shell{display:flex;min-height:100vh}.rail{width:43px;flex:0 0 43px;background:#1b1c1e;border-right:1px solid #303238;display:flex;flex-direction:column;align-items:center;padding:8px 4px;gap:5px;position:fixed;inset:0 auto 0 0;z-index:8}.rail .logo{height:28px;width:30px;display:grid;place-items:center;color:#bfc5ce;font-size:18px;margin-bottom:5px}.rail button{width:32px;height:32px;border:0;border-radius:6px;background:transparent;color:#a7adb7;font-size:16px;display:grid;place-items:center;position:relative}.rail button:hover{background:#2c3037;color:#fff}.rail button.active{background:#263e5a;color:#69aaff;box-shadow:inset 0 0 0 1px #355b82}.rail .spacer{flex:1}.main{margin-left:43px;min-width:0;width:calc(100% - 43px)}.topbar{height:43px;background:#1d1e20;border-bottom:1px solid #34373d;display:flex;align-items:center;justify-content:space-between;padding:0 14px 0 22px;position:sticky;top:0;z-index:5}.top-left{display:flex;align-items:center;gap:14px;color:#d6dae0}.hamb{color:#aab1bb;font-size:15px}.top-right{display:flex;align-items:center;gap:9px}.top-select{border:1px solid #3a3d43;background:#202226;color:#c9ced7;padding:5px 9px;border-radius:5px;font-size:11px}.tiny-icon{color:#aab1bb;border:0;background:none;font-size:14px}.live{width:8px;height:8px;background:#20c87a;border-radius:50%;box-shadow:0 0 8px #20c87a}.profile{width:23px;height:23px;border-radius:50%;background:linear-gradient(135deg,#edc7b2,#67b7b0,#9879c9);border:2px solid #6c7179}
.content{padding:20px 16px 30px;max-width:1800px;margin:auto}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 16px}.heading h1{font-size:19px;margin:0 0 4px;font-weight:650;display:flex;align-items:center;gap:9px}.heading p{margin:0;color:#a0a6b0;font-size:11px}.create{background:var(--blue);color:white;border:0;border-radius:5px;padding:7px 12px;font-size:11px;box-shadow:0 1px 3px #0005}.create:hover{background:#3988e4}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:15px}.metric{height:66px;border:1px solid #3b4657;border-left:2px solid var(--blue);border-radius:6px;background:#1e2735;padding:10px 12px}.metric.green{border-left-color:var(--green)}.metric.orange{border-left-color:var(--orange)}.metric.cyan{border-left-color:var(--cyan)}.metric .label{font-size:9px;letter-spacing:.35px;color:#b9c4d2;text-transform:uppercase}.metric .label em{font-style:normal;color:#4e9eff}.metric strong{display:block;font-size:17px;margin-top:5px;font-weight:650}.metric.green .label{color:#70dba9}.metric.orange .label{color:#efbd68}.metric.cyan .label{color:#67d9e4}
.table-panel{border:1px solid #3a3d43;background:#202226;border-radius:6px;overflow:visible}.table-head{min-height:41px;padding:7px 10px;display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #3b3e45}.table-title{font-size:11px;color:#d5d9df;display:flex;align-items:center;gap:8px}.count{font-size:9px;color:#36c9d2;background:#123b43;padding:3px 5px;border-radius:3px}.filters{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.filters input,.filters select{height:25px;border:1px solid #3d424a;border-radius:5px;background:#202226;color:#c6ccd5;font-size:10px;padding:0 8px;min-width:80px}.filters input{width:145px}.reset{height:25px;border:1px solid #3d424a;border-radius:5px;background:#24272c;color:#c6ccd5;font-size:10px;padding:0 9px}.table-wrap{overflow-x:auto;padding:7px}.table{width:100%;border-collapse:collapse;min-width:850px}.table th{height:27px;background:#2b3542;color:#c4ccd6;text-align:left;font-size:9px;font-weight:600;letter-spacing:.35px;padding:0 9px;white-space:nowrap}.table td{height:40px;border-bottom:1px solid #42464d;padding:5px 9px;font-size:10px;color:#c4c8d0;white-space:nowrap}.table tr:last-child td{border-bottom:0}.table tbody tr:hover{background:#292d33}.name{font-weight:600;color:#dce0e6;font-size:10px}.desc{font-size:9px;color:#8d949f;margin-top:3px}.keycode{font:9px ui-monospace,SFMono-Regular,monospace;background:#3b3e43;color:#c9cdd3;border-radius:3px;padding:3px 5px}.type{font-size:9px;border:1px solid #8d692c;color:#e5b44d;border-radius:3px;padding:3px 5px}.type.standard{border-color:#176c7b;color:#36c7d3}.status{font-size:9px;border:1px solid #3f4a4b;color:#aeb6c0;border-radius:3px;padding:3px 5px}.status.active{border-color:#176744;color:#38d18b;background:#142d24}.status.expiring{border-color:#795a23;color:#e9b14f}.status.revoked{border-color:#733c43;color:#ed727c}.dots{border:0;background:none;color:#c4cad2;font-size:16px;padding:0 6px}.footnote{color:#77808d;font-size:10px;padding:10px 4px}.blank{padding:32px;text-align:center;color:#8f97a3}.view{display:none}.view.active{display:block}
.modal-bg{position:fixed;inset:0;background:#0009;z-index:20;display:none;align-items:center;justify-content:center;padding:16px}.modal-bg.open{display:flex}.modal{width:min(540px,100%);background:#22252a;border:1px solid #454a53;border-radius:9px;box-shadow:0 20px 70px #0009;padding:18px}.modal-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.modal-top h2{font-size:16px;margin:0}.x{border:0;background:none;color:#aeb5c0;font-size:20px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{display:flex;flex-direction:column;gap:5px}.field.full{grid-column:1/-1}.field label{font-size:10px;color:#aeb5c0}.field input,.field select,.field textarea{background:#181a1e;border:1px solid #444a54;color:#e5e8ed;border-radius:5px;padding:9px;font:12px inherit;min-width:0}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.secondary{background:#30343b;color:#d6dbe2;border:1px solid #484d56;border-radius:5px;padding:7px 12px;font-size:11px}.toast{position:fixed;right:18px;bottom:18px;background:#e9edf2;color:#17191d;padding:10px 14px;border-radius:6px;box-shadow:0 4px 20px #0007;z-index:40;display:none;font-size:12px}.toast.show{display:block}.settings-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.setting-card{background:#202226;border:1px solid #3a3e45;border-radius:6px;padding:14px}.setting-card h3{margin:0 0 7px;font-size:12px}.setting-card p{color:#939ba7;font-size:10px;line-height:1.5}.setting-card button{background:#2d333d;border:1px solid #454c58;color:#dbe0e8;padding:6px 9px;border-radius:4px;font-size:10px}
@media(max-width:720px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding:14px 10px}.heading{align-items:flex-start}.heading h1{font-size:17px}.topbar{padding:0 9px}.top-right{gap:5px}.filters input{width:115px}.table-head{align-items:flex-start;flex-direction:column}.filters{width:100%}.settings-grid{grid-template-columns:1fr 1fr}}
@media(max-width:420px){.rail{width:39px;flex-basis:39px}.main{margin-left:39px;width:calc(100% - 39px)}.rail button{width:30px}.cards{gap:7px}.metric{padding:9px;height:62px}.metric strong{font-size:15px}.settings-grid{grid-template-columns:1fr}}
</style></head>
<body>
<div class="shell">
<aside class="rail" id="rail">
<div class="logo">◈</div>
<button class="active" title="API Keys" data-view="api">▣</button>
<button title="Dashboard" data-view="dashboard">▦</button>
<button title="Key Generator" data-view="generator">⌘</button>
<button title="Banned Keys" data-view="banned">⊘</button>
<button title="Analytics" data-view="analytics">⌁</button>
<button title="Users" data-view="users">♙</button>
<button title="Logs" data-view="logs">≡</button>
<button title="Settings" data-view="settings">⚙</button>
<button title="Theme Studio" data-view="themes">◐</button>
<button title="Security" data-view="security">⬡</button>
<button title="Backup" data-view="backup">⇧</button>
<div class="spacer"></div><button title="Help" data-view="help">ⓘ</button>
</aside>
<div class="main">
<header class="topbar"><div class="top-left"><span class="hamb">☰</span><span id="topTitle">API Keys</span></div><div class="top-right"><select class="top-select"><option>◷ &nbsp; Last 1 hour</option><option>Last 24 hours</option><option>Last 7 days</option><option>Last 30 days</option></select><select class="top-select"><option>10s</option><option>30s</option><option>1m</option><option>Off</option></select><button class="tiny-icon" title="Refresh" onclick="renderAll()">⟳</button><span class="live"></span><button class="tiny-icon" title="Theme" onclick="go('themes')">☼</button><div class="profile" title="Admin profile"></div></div></header>
<main class="content">
<section class="view active" id="view-api">
<div class="heading"><div><h1>⚿ API Keys</h1><p>Manage API keys for programmatic access</p></div><button class="create" onclick="openCreate()">＋ Create API Key</button></div>
<div class="cards">
<div class="metric"><div class="label">▥ &nbsp; Total Keys <em>(1h)</em></div><strong id="mTotal">25</strong></div>
<div class="metric green"><div class="label">● &nbsp; Active <em>(1h)</em></div><strong id="mActive">7</strong></div>
<div class="metric orange"><div class="label">▣ &nbsp; Service Keys <em>(1h)</em></div><strong id="mService">3</strong></div>
<div class="metric cyan"><div class="label">⌁ &nbsp; Total Usage <em>(1h)</em></div><strong id="mUsage">48K</strong></div>
</div>
<div class="table-panel">
<div class="table-head"><div class="table-title">♧ &nbsp; API Key List <span class="count" id="rowCount">25 API keys</span></div><div class="filters"><input id="search" placeholder="⌕ Search by name..." oninput="renderRows()"><select id="statusFilter" onchange="renderRows()"><option value="">Status</option><option>Active</option><option>Inactive</option><option>Expiring Soon</option><option>Revoked</option></select><select id="typeFilter" onchange="renderRows()"><option value="">Key Type</option><option>Service</option><option>Standard</option></select><button class="reset" onclick="resetFilters()">↻ Reset</button></div></div>
<div class="table-wrap"><table class="table"><thead><tr><th>NAME　↕</th><th>KEY</th><th>TYPE　↕</th><th>STATUS　↕</th><th>RATE LIMIT</th><th>USAGE</th><th>LAST USED</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody id="rows"></tbody></table></div>
</div><div class="footnote">Showing API keys stored in this browser · Demo data is local only</div>
</section>
<section class="view" id="view-dashboard"><div class="heading"><div><h1>▦ Dashboard</h1><p>API key activity overview</p></div><button class="create" onclick="openCreate()">＋ Create API Key</button></div><div class="cards" id="dashCards"></div><div class="table-panel"><div class="table-head">Recent API key activity</div><div class="table-wrap"><table class="table"><thead><tr><th>EVENT</th><th>DETAIL</th><th>TIME</th></tr></thead><tbody id="recent"></tbody></table></div></div></section>
<section class="view" id="view-generator"><div class="heading"><div><h1>⌘ Key Generator</h1><p>Generate single or bulk API keys</p></div></div><div class="table-panel" style="padding:16px"><div class="formgrid"><div class="field"><label>Key name</label><input id="genName" placeholder="e.g. Production API"></div><div class="field"><label>Key type</label><select id="genType"><option>Standard</option><option>Service</option></select></div><div class="field"><label>Rate limit</label><select id="genRate"><option>100/min</option><option>500/min</option><option>1000/min</option><option>5000/min</option></select></div><div class="field"><label>How many keys</label><input id="genCount" type="number" min="1" max="100" value="1"></div><div class="field full"><label>Description</label><input id="genDesc" placeholder="What will this key be used for?"></div></div><button class="create" style="margin-top:14px" onclick="generateKeys()">Generate API Key(s)</button><div id="generated" style="margin-top:12px"></div></div></section>
<section class="view" id="view-banned"><div class="heading"><div><h1>⊘ Banned Keys</h1><p>Revoked and blocked API keys</p></div></div><div class="table-panel"><div class="table-head">Blocked keys <button class="create" onclick="openBan()">＋ Ban key</button></div><div class="table-wrap"><table class="table"><thead><tr><th>KEY</th><th>REASON</th><th>DATE</th><th>ACTION</th></tr></thead><tbody id="bannedRows"></tbody></table></div></div></section>
<section class="view" id="view-analytics"><div class="heading"><div><h1>⌁ Analytics</h1><p>Usage and key statistics</p></div></div><div class="cards" id="analyticsCards"></div><div class="table-panel" style="padding:15px"><h3 style="font-size:12px">Usage overview</h3><p style="color:#9299a5;font-size:11px">Usage numbers are sample/local demo values. Connect a backend to display real API traffic.</p></div></section>
<section class="view" id="view-users"><div class="heading"><div><h1>♙ Admin Users</h1><p>Local administrator directory</p></div><button class="create" onclick="openUser()">＋ Add user</button></div><div class="table-panel"><div class="table-wrap"><table class="table"><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="userRows"></tbody></table></div></div></section>
<section class="view" id="view-logs"><div class="heading"><div><h1>≡ Activity Logs</h1><p>Recent admin actions</p></div><button class="create" onclick="downloadLogs()">Export logs</button></div><div class="table-panel"><div class="table-wrap"><table class="table"><thead><tr><th>EVENT</th><th>DETAIL</th><th>TIME</th></tr></thead><tbody id="logRows"></tbody></table></div></div></section>
<section class="view" id="view-settings"><div class="heading"><div><h1>⚙ Settings</h1><p>Manage panel preferences</p></div><button class="create" onclick="saveSettings()">Save changes</button></div><div class="settings-grid" id="settingsGrid"></div></section>
<section class="view" id="view-themes"><div class="heading"><div><h1>◐ Theme Studio</h1><p>Choose a dashboard appearance</p></div></div><div class="settings-grid" id="themeGrid"></div></section>
<section class="view" id="view-security"><div class="heading"><div><h1>⬡ Security</h1><p>Security recommendations</p></div></div><div class="settings-grid" id="securityGrid"></div></section>
<section class="view" id="view-backup"><div class="heading"><div><h1>⇧ Backup & Import</h1><p>Export and restore local API key records</p></div></div><div class="table-panel" style="padding:16px"><p style="color:#a0a6b0">Export all keys as TXT, import keys from TXT (one key per line), or save a full JSON backup.</p><button class="create" onclick="exportTxt()">Download keys.txt</button> <label class="secondary">Import TXT<input type="file" accept=".txt,text/plain" hidden onchange="importTxt(this.files[0]);this.value=''"></label> <button class="secondary" onclick="backupJson()">Download JSON backup</button><label class="secondary">Restore JSON<input type="file" accept=".json" hidden onchange="restoreJson(this.files[0])"></label></div></section>
<section class="view" id="view-help"><div class="heading"><div><h1>ⓘ Help</h1><p>About this dashboard</p></div></div><div class="table-panel" style="padding:16px;color:#aab1bb;line-height:1.7">This is a front-end demo. API key records are stored in browser localStorage. Real API authentication, permissions, rate limits and server-side revocation require a backend.</div></section>
</main></div></div>
<div class="modal-bg" id="modalBg"><div class="modal"><div class="modal-top"><h2 id="modalTitle">Create API Key</h2><button class="x" onclick="closeModal()">×</button></div><div id="modalBody"></div></div></div><div class="toast" id="toast"></div>
<script>
const $=s=>document.querySelector(s),uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);
const themes=[['Graphite','#171819','#202226'],['Midnight','#0d1420','#182335'],['Deep Blue','#101a2b','#1a2a42'],['Pure Black','#08090b','#15171b'],['Slate','#202832','#2b3542'],['Emerald','#101f1b','#1b3028'],['Violet','#1d1830','#2a2340'],['Crimson','#25171b','#382329'],['Ocean','#10232b','#1c343f'],['Light','#edf0f4','#fff']];
let records=JSON.parse(localStorage.getItem('tf_api_keys')||'null')||[
['Monitoring Agent','Service','Inactive','500/min','1,812','Never','2026-01-31 15:01'],['Development API','Service','Active','5000/min','5,727','2026-02-04 00:43','2026-01-26 15:01'],['Monitoring Agent','Service','Expiring Soon','5000/min','8,434','2026-02-04 11:10','2026-01-18 15:01'],['Monitoring Agent','Standard','Inactive','100/min','82','Never','2026-01-15 15:01'],['Production API','Standard','Active','100/min','7,481','2026-02-03 17:47','2026-01-03 15:01'],['Mobile App','Standard','Active','5000/min','4,390','2026-02-04 07:13','2025-12-31 15:01'],['CI/CD Pipeline','Standard','Active','500/min','6,831','2026-02-04 08:15','2025-12-15 15:01'],['Test Environment','Standard','Revoked','500/min','1,388','Never','2025-12-07 15:01'],['CI/CD Pipeline','Standard','Active','1000/min','6,460','2026-02-03 20:06','2025-11-26 15:01']
].map((r,i)=>({id:uid(),name:r[0],type:r[1],status:r[2],rate:r[3],usage:r[4],last:r[5],created:r[6],key:'tfsk_'+Array.from({length:16},()=>Math.random().toString(36)[2]).join('')}));
let banned=JSON.parse(localStorage.getItem('tf_api_banned')||'[]'),users=JSON.parse(localStorage.getItem('tf_api_users')||'[]'),logs=JSON.parse(localStorage.getItem('tf_api_logs')||'[]');
function persist(){localStorage.setItem('tf_api_keys',JSON.stringify(records));localStorage.setItem('tf_api_banned',JSON.stringify(banned));localStorage.setItem('tf_api_users',JSON.stringify(users));localStorage.setItem('tf_api_logs',JSON.stringify(logs))}
function log(event,detail){logs.unshift({event,detail,time:new Date().toLocaleString()});logs=logs.slice(0,300);persist()}
function notify(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function go(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('#view-'+v).classList.add('active');document.querySelectorAll('.rail button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#topTitle').textContent=({api:'API Keys',dashboard:'Dashboard',generator:'Key Generator',banned:'Banned Keys',analytics:'Analytics',users:'Admin Users',logs:'Activity Logs',settings:'Settings',themes:'Theme Studio',security:'Security',backup:'Backup & Import',help:'Help'})[v];renderAll()}
$('#rail').addEventListener('click',e=>{let b=e.target.closest('button[data-view]');if(b)go(b.dataset.view)});
function renderRows(){let q=$('#search').value.toLowerCase(),st=$('#statusFilter').value,ty=$('#typeFilter').value;let arr=records.filter(r=>(!q||r.name.toLowerCase().includes(q)||r.key.toLowerCase().includes(q))&&(!st||r.status===st)&&(!ty||r.type===ty));$('#rowCount').textContent=arr.length+' API keys';$('#rows').innerHTML=arr.map(r=>`<tr><td><div class="name">${esc(r.name)}</div><div class="desc">API key for ${esc(r.name.toLowerCase())} access</div></td><td><span class="keycode">${esc(r.key.slice(0,4)+'…'+r.key.slice(-8))}</span></td><td><span class="type ${r.type==='Standard'?'standard':''}">${r.type}</span></td><td><span class="status ${statusClass(r.status)}">${r.status}</span></td><td>${r.rate}</td><td>${r.usage}</td><td>${r.last}</td><td>${r.created}</td><td><button class="dots" title="Actions" onclick="rowMenu('${r.id}')">⋮</button></td></tr>`).join('')||'<tr><td colspan="9" class="blank">No API keys found</td></tr>';$('#mTotal').textContent=records.length+16;$('#mActive').textContent=records.filter(r=>r.status==='Active').length;$('#mService').textContent=records.filter(r=>r.type==='Service').length;$('#mUsage').textContent='48K'}
function statusClass(s){return s==='Active'?'active':s==='Expiring Soon'?'expiring':s==='Revoked'?'revoked':''}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function resetFilters(){$('#search').value='';$('#statusFilter').value='';$('#typeFilter').value='';renderRows()}
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalBg').classList.add('open')}function closeModal(){$('#modalBg').classList.remove('open')}
function openCreate(){modal('Create API Key',`<form onsubmit="createRecord(event)"><div class="formgrid"><div class="field full"><label>Name</label><input id="newName" required placeholder="e.g. Production API"></div><div class="field"><label>Key Type</label><select id="newType"><option>Standard</option><option>Service</option></select></div><div class="field"><label>Rate Limit</label><select id="newRate"><option>100/min</option><option>500/min</option><option>1000/min</option><option>5000/min</option></select></div><div class="field full"><label>Description</label><input id="newDesc" placeholder="API key description"></div></div><div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="create">Create API Key</button></div></form>`)}
function makeKey(){let a=new Uint8Array(24);crypto.getRandomValues(a);return 'tfsk_'+Array.from(a,x=>x.toString(16).padStart(2,'0')).join('')}
function createRecord(e){e.preventDefault();let r={id:uid(),name:$('#newName').value,type:$('#newType').value,status:'Active',rate:$('#newRate').value,usage:'0',last:'Never',created:new Date().toISOString().slice(0,16).replace('T',' '),key:makeKey()};records.unshift(r);persist();log('API key created',r.name);closeModal();renderAll();notify('API key created');modal('API Key Created',`<p style="color:#aab1bb;font-size:11px">Copy this key now. It is shown in full only in this dialog.</p><input style="width:100%;background:#17191d;color:#dce2e9;border:1px solid #454b55;padding:10px;border-radius:5px" id="createdKey" value="${r.key}" readonly><div class="modal-actions"><button class="secondary" onclick="navigator.clipboard?.writeText($('#createdKey').value);notify('Copied')">Copy key</button><button class="create" onclick="closeModal()">Done</button></div>`)}
function rowMenu(id){let r=records.find(x=>x.id===id);if(!r)return;modal('API Key Actions',`<p style="color:#aab1bb;font-size:11px">${esc(r.name)} · ${esc(r.type)} · ${esc(r.status)}</p><div class="modal-actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="secondary" onclick="copyKey('${id}')">Copy key</button><button class="secondary" onclick="toggleRecord('${id}')">${r.status==='Active'?'Deactivate':'Activate'}</button><button class="secondary" onclick="banRecord('${id}')">Revoke / Ban</button><button class="secondary" onclick="deleteRecord('${id}')">Delete</button></div>`)}
function copyKey(id){let r=records.find(x=>x.id===id);if(r){navigator.clipboard?.writeText(r.key);notify('Key copied')}}
function toggleRecord(id){let r=records.find(x=>x.id===id);r.status=r.status==='Active'?'Inactive':'Active';persist();log('Key status changed',r.name+' → '+r.status);closeModal();renderAll()}
function banRecord(id){let r=records.find(x=>x.id===id);banned.unshift({id:uid(),key:r.key,reason:'Manually revoked',date:new Date().toLocaleString()});records=records.filter(x=>x.id!==id);persist();log('Key revoked',r.name);closeModal();renderAll()}
function deleteRecord(id){records=records.filter(x=>x.id!==id);persist();log('Key deleted',id);closeModal();renderAll()}
function generateKeys(){let n=Math.max(1,Math.min(100,+$('#genCount').value||1)),name=$('#genName').value||'Generated API',out=[];for(let i=0;i<n;i++){let r={id:uid(),name,type:$('#genType').value,status:'Active',rate:$('#genRate').value,usage:'0',last:'Never',created:new Date().toISOString().slice(0,16).replace('T',' '),key:makeKey()};records.unshift(r);out.push(r.key)}persist();log('Keys generated',n+' keys');$('#generated').innerHTML=`<div style="color:#53d69b;font-size:11px;margin-bottom:6px">${n} key(s) generated</div><textarea style="width:100%;height:100px;background:#17191d;color:#dce2e9;border:1px solid #444;padding:8px" readonly>${out.join('\n')}</textarea><button class="secondary" onclick="navigator.clipboard?.writeText(${JSON.stringify(out.join('\n'))});notify('Copied')">Copy all</button>`;renderAll()}
function openBan(){modal('Ban API Key',`<form onsubmit="banManual(event)"><div class="field"><label>API Key</label><input id="banValue" required></div><div class="field" style="margin-top:10px"><label>Reason</label><input id="banReason" required></div><div class="modal-actions"><button class="create">Ban key</button></div></form>`)}
function banManual(e){e.preventDefault();banned.unshift({id:uid(),key:$('#banValue').value,reason:$('#banReason').value,date:new Date().toLocaleString()});records=records.filter(r=>r.key!==$('#banValue').value);persist();log('Key banned',$('#banValue').value);closeModal();renderAll()}
function renderBanned(){$('#bannedRows').innerHTML=banned.map(b=>`<tr><td><span class="keycode">${esc(b.key)}</span></td><td>${esc(b.reason)}</td><td>${esc(b.date)}</td><td><button class="secondary" onclick="unban('${b.id}')">Unban</button></td></tr>`).join('')||'<tr><td colspan="4" class="blank">No banned keys</td></tr>'}
function unban(id){banned=banned.filter(x=>x.id!==id);persist();renderAll()}
function renderAll(){renderRows();renderBanned();$('#dashCards').innerHTML=[['Total Keys',records.length],['Active',records.filter(r=>r.status==='Active').length],['Banned',banned.length],['Usage','48K']].map(x=>`<div class="metric"><div class="label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');$('#analyticsCards').innerHTML=$('#dashCards').innerHTML;$('#recent').innerHTML=logs.slice(0,8).map(l=>`<tr><td>${esc(l.event)}</td><td>${esc(l.detail)}</td><td>${esc(l.time)}</td></tr>`).join('')||'<tr><td colspan="3" class="blank">No activity yet</td></tr>';$('#logRows').innerHTML=logs.map(l=>`<tr><td>${esc(l.event)}</td><td>${esc(l.detail)}</td><td>${esc(l.time)}</td></tr>`).join('')||'<tr><td colspan="3" class="blank">No logs</td></tr>';$('#userRows').innerHTML=users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>Active</td><td><button class="secondary" onclick="users=users.filter(x=>x.id!=='${u.id}');persist();renderAll()">Remove</button></td></tr>`).join('')||'<tr><td colspan="5" class="blank">No additional admins</td></tr>'}
function openUser(){modal('Add Admin User',`<form onsubmit="addUser(event)"><div class="field"><label>Name</label><input id="userName" required></div><div class="field" style="margin-top:10px"><label>Email</label><input id="userEmail" type="email" required></div><div class="field" style="margin-top:10px"><label>Role</label><select id="userRole"><option>Admin</option><option>Viewer</option><option>Developer</option></select></div><div class="modal-actions"><button class="create">Add user</button></div></form>`)}
function addUser(e){e.preventDefault();users.push({id:uid(),name:$('#userName').value,email:$('#userEmail').value,role:$('#userRole').value});persist();closeModal();renderAll()}
function renderSettings(){let opts=['Email notifications','Auto refresh dashboard','Require key descriptions','Show full key on create','Confirm before revoke','Record admin activity','Compact table rows','Show usage metrics','Enable maintenance mode'];$('#settingsGrid').innerHTML=opts.map((x,i)=>`<div class="setting-card"><h3>${x}</h3><p>Configure ${x.toLowerCase()} for this local dashboard.</p><label style="font-size:10px;color:#cbd1da"><input type="checkbox" ${i<6?'checked':''}> Enabled</label></div>`).join('')}
function renderThemes(){$('#themeGrid').innerHTML=themes.map(t=>`<div class="setting-card" style="background:${t[1]}"><div style="height:26px;background:${t[2]};border:1px solid #555;border-radius:4px;margin-bottom:9px"></div><h3>${t[0]}</h3><button onclick="applyTheme('${t[1]}','${t[2]}')">Apply theme</button></div>`).join('')}
function applyTheme(bg,panel){document.documentElement.style.setProperty('--bg',bg);document.documentElement.style.setProperty('--panel',panel);notify('Theme applied')}
function renderSecurity(){$('#securityGrid').innerHTML=['Use HTTPS in production','Store secrets on the server','Validate keys server-side','Use rate limiting','Keep audit logs','Rotate API secrets regularly'].map(x=>`<div class="setting-card"><h3>⬡ ${x}</h3><p>Recommended for a production deployment.</p><span style="color:#eab45c;font-size:10px">Review required</span></div>`).join('')}
function exportTxt(){let lines=records.map(r=>r.key);download('api-keys.txt',lines.join('\n')+(lines.length?'\n':''),'text/plain');log('TXT export',lines.length+' keys');notify('TXT downloaded')}
function importTxt(file){if(!file)return;let reader=new FileReader();reader.onload=()=>{let lines=String(reader.result).split(/\r?\n/).map(x=>x.trim()).filter(Boolean),known=new Set(records.map(r=>r.key.toLowerCase())),banSet=new Set(banned.map(b=>b.key.toLowerCase())),added=0,skipped=0;for(let key of lines){if(known.has(key.toLowerCase())||banSet.has(key.toLowerCase())){skipped++;continue}records.unshift({id:uid(),name:'Imported API Key',type:'Standard',status:'Active',rate:'100/min',usage:'0',last:'Never',created:new Date().toISOString().slice(0,16).replace('T',' '),key});known.add(key.toLowerCase());added++}persist();log('TXT import',added+' added; '+skipped+' skipped');renderAll();notify(added+' added · '+skipped+' skipped')};reader.readAsText(file)}
function backupJson(){download('api-keys-backup.json',JSON.stringify({records,banned,users,logs},null,2),'application/json')}
function restoreJson(file){if(!file)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);records=d.records||records;banned=d.banned||[];users=d.users||[];logs=d.logs||[];persist();renderAll();notify('Backup restored')}catch{notify('Invalid JSON backup')}};r.readAsText(file)}
function download(name,data,type){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
function downloadLogs(){download('api-activity.csv','Event,Detail,Time\n'+logs.map(x=>[x.event,x.detail,x.time].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')}
function saveSettings(){notify('Settings saved locally');log('Settings saved','Dashboard preferences')}
renderSettings();renderThemes();renderSecurity();renderAll();
</script></body></html>
